import {encodeWav} from './stems.js';
const $=s=>document.querySelector(s),sleep=ms=>new Promise(r=>setTimeout(r,ms)),assert=(v,m)=>{if(!v)throw Error(m);};
const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(v=>v.toString(16).padStart(2,'0')).join('');
const files=['app.js','engine.js','panels.js','deck-midi.js','track-gain.js','styles.css','local-audio-library.js','fx-tempo-capture-worklet.js','track-gain-harness.js'];
const identities=async()=>Object.fromEntries(await Promise.all(files.map(async f=>[f,await hash(await(await fetch(f,{cache:'no-store'})).arrayBuffer())])));
const click=s=>{assert($(s),'Missing '+s);$(s).click();},input=(s,v)=>{const e=$(s);assert(e,'Missing '+s);e.value=String(v);e.dispatchEvent(new Event('input',{bubbles:true}));},change=(s,v)=>{const e=$(s);assert(e,'Missing '+s);if(e.type==='checkbox')e.checked=v;else e.value=String(v);e.dispatchEvent(new Event('change',{bubbles:true}));};
async function until(fn,label){const end=performance.now()+30000;while(!fn()){assert(performance.now()<end,label+' timed out');await sleep(10);}}
function base64(bytes){let s='';for(let n=0;n<bytes.length;n+=16384)s+=String.fromCharCode(...bytes.subarray(n,n+16384));return btoa(s);}
function amplitude(a,sr,hz){let re=0,im=0;for(let n=0;n<a.length;n++){assert(Number.isFinite(a[n]),'Nonfinite output sample');re+=a[n]*Math.cos(2*Math.PI*hz*n/sr);im+=a[n]*Math.sin(2*Math.PI*hz*n/sr);}return 2*Math.hypot(re,im)/a.length;}
let app,r,witness;
function output(){const safe={...r,cases:r.cases.map(c=>({...c,pcm:c.pcm?{...c.pcm,base64:'Retained in original'}:null})),recordings:r.recordings.map(c=>({...c,base64:'Retained in original'}))};$('#gain-original').textContent=JSON.stringify(r,null,2);$('#gain-results').textContent=JSON.stringify(safe,null,2);sessionStorage.setItem('track-gain-report',JSON.stringify(r));$('#gain-status').textContent=r.completed?'Scoped stored track gain audio and restored playback passed':r.errors.length?'Failed: '+r.errors.map(e=>e.message).join('; '):'Ready for saved-file playback verification';}
const track=id=>app.state.tracks.find(t=>t.id===id),button=(i,a)=>`[data-deck="${i}"][data-action="${a}"]`,gain=i=>`[data-track-gain="${i}"]`;
function select(id){click(`#tracks [data-track="${id}"]`);}
async function load(i,id){select(id);click(button(i,'load'));await until(()=>app.state.decks[i].track?.id===id&&app.engine.buffers.has(id),'Actual deck load');}
async function setupWitness(){const {engine}=app;await engine.resume();engine.audioMonitor.mutePhysical(true);await until(()=>engine.audioMonitor.snapshot().physicalMuted,'Physical mute');await engine.ctx.audioWorklet.addModule(new URL('./fx-tempo-capture-worklet.js',import.meta.url));witness=new AudioWorkletNode(engine.ctx,'open-play-fx-tempo-capture-test',{numberOfInputs:1,numberOfOutputs:1,outputChannelCount:[1],channelCount:1,channelCountMode:'explicit',channelInterpretation:'discrete'});const split=engine.ctx.createChannelSplitter(2);engine.masterOutput.output.connect(split);split.connect(witness,0);witness.connect(engine.ctx.destination);}
async function sample(name,expected,action){const {engine,state}=app;$('#gain-status').textContent='Running '+name;await action();await sleep(300);const id=r.cases.length,raw=await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('Capture timed out')),5000);witness.port.onmessage=({data})=>{if(data.type==='done'&&data.id===id){clearTimeout(timer);resolve(data);}};witness.port.postMessage({type:'capture',id,frames:Math.round(engine.ctx.sampleRate*.3)});});const bytes=new Uint8Array(raw.data.buffer),measured=[440,880].map(hz=>amplitude(raw.data,engine.ctx.sampleRate,hz)),c={name,expected,measured,deckTargets:[...engine.deckTrackGainDB],trackA:track(r.a).trackGainDb,trim:state.decks[0].trim??1,pcm:{frames:raw.data.length,startFrame:raw.startFrame,sha256:await hash(bytes),base64:base64(bytes)}};r.cases.push(c);c.errors=measured.map((v,i)=>expected[i]>0?Math.abs(v/expected[i]-1):v);c.passed=c.errors.every((v,i)=>v<=(expected[i]>0?.02:.000001));assert(c.passed,'Output gain mismatch in '+name);assert(c.trim===1,'Track gain moved channel trim');if(state.decks[1].track?.id===r.a)assert(engine.deckTrackGainDB[0]===engine.deckTrackGainDB[1],'Same file gains must match on both decks');}
async function finishRecord(){const {engine}=app;if(engine.recording){const blob=await engine.recordStop(),bytes=new Uint8Array(await blob.arrayBuffer()),b=await engine.ctx.decodeAudioData(bytes.buffer.slice(0));for(let c=0;c<b.numberOfChannels;c++)for(const v of b.getChannelData(c))assert(Number.isFinite(v),'Nonfinite whole recording');r.recordings.push({bytes:bytes.length,sha256:await hash(bytes),format:blob.type,base64:base64(bytes),duration:b.duration,frames:b.length,sampleRate:b.sampleRate,channels:b.numberOfChannels});}}
async function run(){const {state,engine}=app;r={startedAt:new Date().toISOString(),completed:false,scope:'Owned production File-input change imports (synthetic chooser), actual deck loading/track gain/analysis/MIDI/sampler advanced/output controls, independent channel0Float32 windows, whole recordings and saved-file playback after full reload. Manual gain, not perceived Auto Gain/native/hardware acceptance.',criteria:{settlingSeconds:.3,captureSeconds:.3,maximumRelativeAmplitudeError:.02,maximumAbsentTone:.000001},cases:[],recordings:[],errors:[]};$('#gain-run').disabled=true;
 try{
  r.sourceBefore=await identities();await setupWitness();await until(()=>!state.analysis,'Initial analysis');for(const d of state.decks)engine.pause(d);engine.stopAllSamples();for(const bank of state.fx)for(const slot of bank)slot.on=false;engine.configureFX(state.fx,state.fxRoutes||[],state.decks.map(()=>120),state.fxTempo);input('#master-level',0);input('#crossfader',0);for(let i=0;i<2;i++){input(`[data-mix="${i}:level"]`,.8);input(`[data-mix="${i}:trim"]`,1);}const sr=44100,transfer=new DataTransfer();r.files=[];
  for(const [name,hz,amp]of [['A',440,.02],['B',880,.03]]){const b=engine.ctx.createBuffer(2,sr*8,sr);for(let c=0;c<2;c++){const a=b.getChannelData(c);for(let n=0;n<a.length;n++)a[n]=amp*Math.sin(2*Math.PI*hz*n/sr);}const bytes=encodeWav(b),digest=await hash(bytes);r.files.push({id:'local-'+digest,sha256:digest,name});transfer.items.add(new File([bytes],`track-gain-${name}.wav`,{type:'audio/wav'}));}
  $('#audio-files').files=transfer.files;$('#audio-files').dispatchEvent(new Event('change',{bubbles:true}));await until(()=>r.files.every(f=>track(f.id)?.storage==='saved')&&!state.analysis,'File import, saved originals and analysis');r.a=r.files[0].id;r.b=r.files[1].id;await load(0,r.a);await load(1,r.a);await until(()=>!state.analysis,'Measured track result');r.measuredGain=track(r.a).analysisResult?.gain;assert(Number.isFinite(r.measuredGain?.recommendedDb),'Actual measured RMS recommendation');
  Object.assign(state.decks[0],{loop:true,loopIn:0,loopOut:8});input(gain(0),0);click(button(0,'play'));await until(()=>state.decks[0].playing,'Actual deck Play');await engine.recordStart();const h=10**(-3/20),a=.02*.8*h;
  await sample('deck neutral',[a,0],async()=>{});await sample('GUI track plus24',[a*10**(24/20),0],async()=>input(gain(0),24));await sample('Control reset0',[a,0],async()=>$(gain(0)).dispatchEvent(new MouseEvent('click',{bubbles:true,ctrlKey:true})));
  click('[data-panel="midi"]');click('#midi-reset');for(const [id,v]of [['#midi-target','Deck 1 track gain'],['#midi-type','CC'],['#midi-channel',3],['#midi-number',20],['#midi-encoding','7-bit absolute']])$(id).value=String(v);click('#midi-add');const send=v=>{for(const [id,x]of [['#midi-type','CC'],['#midi-channel',3],['#midi-number',20],['#midi-test-value',v]])$(id).value=String(x);click('#midi-send');};await sample('MIDI minimum minus24',[a*10**(-24/20),0],async()=>send(0));await sample('MIDI center0',[a,0],async()=>send(64));click('#modal-close');
  input(gain(0),6);click(button(0,'play'));await load(0,r.b);await load(0,r.a);Object.assign(state.decks[0],{loop:true,loopIn:0,loopOut:8});click(button(0,'play'));await until(()=>state.decks[0].playing,'Reload same track playback');await sample('reload track recalls plus6',[a*10**(6/20),0],async()=>{});
  select(r.a);click('[data-panel="analysis"]');await sample('apply measured RMS suggestion as stored track gain',[a*10**(r.measuredGain.recommendedDb/20),0],async()=>click('#analysis-gain'));click('#modal-close');click(button(0,'play'));input(gain(0),6);
  click('[data-panel="sampler"]');select(r.a);click('[data-sample="0:load"]');select(r.b);click('[data-sample="1:load"]');for(let i=0;i<2;i++)change(`[data-sample-repeat="${i}"]`,true);click('[data-sample="0:play"]');click('[data-sample="1:play"]');await until(()=>engine.samples?.has(0)&&engine.samples?.has(1),'Actual sampler voices');const sa=.02*.8*.5*h,sb=.03*.8*.5*h;
  await sample('sampler master A plus6 B neutral',[sa*10**(6/20),sb],async()=>{});click('[data-sample="0:advanced"]');await sample('sampler advanced shared plus12',[sa*10**(12/20),sb],async()=>input('#sample-gain',12));click('#sample-apply');
  await sample('sampler deck route no double track gain',[sa*10**(12/20)*.8,sb*.8],async()=>change('#sampler-output','Deck 1'));click('[data-sample="0:advanced"]');await sample('sampler edit shared minus6 only A',[sa*10**(-6/20)*.8,sb*.8],async()=>input('#sample-gain',-6));click('#sample-apply');await sample('sampler return master no channel attenuation',[sa*10**(-6/20),sb],async()=>change('#sampler-output','Master'));await sample('sampler stop all silence',[0,0],async()=>click('#sampler-stop-all'));input(gain(0),6);r.savedGain=track(r.a).trackGainDb;
 }catch(e){r.errors.push({message:e.message,stack:e.stack});}finally{for(const d of state.decks)engine.pause(d);engine.stopAllSamples();await finishRecord();r.sourceAfter=await identities();r.sourceStable=JSON.stringify(r.sourceBefore)===JSON.stringify(r.sourceAfter);output();$('#gain-reload').hidden=false;}}
async function restoredPlay(){const {engine,state}=app;$('#gain-restored-play').disabled=true;try{await setupWitness();await until(()=>r.files.every(f=>track(f.id)?.storage==='saved'),'Saved File restoration');r.reload={gain:track(r.a).trackGainDb,legacy:track(r.a).sampleGain,files:[]};for(const f of r.files){const t=track(f.id),original=await t.readFile();r.reload.files.push({id:t.id,sha256:await hash(await original.arrayBuffer())});}assert(r.reload.files.every((f,i)=>f.sha256===r.files[i].sha256)&&r.reload.gain===6&&r.reload.legacy===6,'Saved original files/gain must restore exactly');await load(0,r.a);Object.assign(state.decks[0],{loop:true,loopIn:0,loopOut:8});click(button(0,'play'));await until(()=>state.decks[0].playing,'Restored actual file Play');await engine.recordStart();await sample('saved File actual playback plus6',[.02*.8*10**(-3/20)*10**(6/20),0],async()=>{});}catch(e){r.errors.push({message:e.message,stack:e.stack});}finally{for(const d of state.decks)engine.pause(d);engine.stopAllSamples();await finishRecord();r.sourceReload=await identities();r.completed=r.cases.length===14&&r.cases.every(c=>c.passed)&&r.sourceStable&&JSON.stringify(r.sourceReload)===JSON.stringify(r.sourceBefore)&&!r.errors.length;r.finishedAt=new Date().toISOString();output();}}
$('#gain-run').onclick=run;$('#gain-restored-play').onclick=restoredPlay;$('#gain-reload').onclick=()=>{sessionStorage.setItem('track-gain-reload','yes');location.reload();};
async function boot(){const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const n of [...parsed.body.children])if(n.tagName!=='SCRIPT')document.body.append(n);await import('./app.js');await until(()=>window.openPlay?.state.decks[0].track,'Actual app');app=window.openPlay;if(sessionStorage.getItem('track-gain-reload')==='yes'){sessionStorage.removeItem('track-gain-reload');r=JSON.parse(sessionStorage.getItem('track-gain-report'));$('#gain-run').hidden=true;$('#gain-restored-play').hidden=false;output();}else{$('#gain-run').disabled=false;$('#gain-status').textContent='Ready for shared track gain workflow';}}
boot().catch(e=>$('#gain-status').textContent=e.message);
